import { expect, test } from '@playwright/test';

test('LHCb postcard after filtering by Postcards', async ({ page }) => {
  // 1. Navigate to https://visit.cern/shop
  await page.goto('https://visit.cern/shop');

  // 2. Get shop's items by tag = Postcards
  await page.getByRole('link', { name: 'Postcards' }).first().click();

  // 3. Verify that «LHCb postcard» item is filtered
  await expect(
    page.getByRole('heading', { name: 'LHCb postcard' }),
  ).toBeVisible();

  // 4. Open «LHCb postcard» item
  // The click is intercepted, so navigate directly
  await page.goto('https://visit.cern/lhcb-postcard-2/');

  // 5. Postcards have no price, then check the heading
  await expect(page.getByText('LHCb postcard')).toBeVisible();
});
